import { motion } from "framer-motion";
import { ArrowRight } from "lucide-react";

import profile from "../assets/avatar1.png";
// import HorizontalGallery from "./HorizontalGallery";

export default function Hero() {
  return (
    <section className="relative min-h-screen bg-[#0b0b0b] overflow-hidden">

      {/* Horizontal Gallery */}
      {/* <HorizontalGallery /> */}

      {/* Background Gradient */}
      <div className="absolute inset-0 bg-gradient-to-b from-transparent via-transparent to-black z-[1]" />

      <div className="max-w-7xl mx-auto bg-[#040210] relative h-screen flex items-end">

        {/* Left Content */}
        <motion.div
          initial={{
            opacity: 0,
            y: 60,
          }}
          animate={{
            opacity: 1,
            y: 0,
          }}
          transition={{
            duration: .8,
          }}
          className="pb-20 z-20 w-1/2"
        >
          <p className="uppercase font-serif tracking-[2px] text-[#8b7355] mb-6">
            HI, I'M SUPRIYA
          </p>

          <h1 className="text-white text-7xl leading-[0.95] font-serif">
            Product &
            <br />
            UX Designer
          </h1>

          <button type="button" className="mt-10 flex items-center gap-4 bg-white text-black rounded-full px-6 py-4 hover:gap-6 duration-300">

            <div className="bg-black rounded-full p-2">
              <ArrowRight
                className="text-white"
                size={18}
              />
            </div>

            Start a Project

          </button>
        </motion.div>

        {/* Portrait */}
        <motion.div
          initial={{
            opacity: 0,
            scale: .8,
          }}
          animate={{
            opacity: 1,
            scale: 1,
          }}
          transition={{
            delay: .3,
            duration: 1,
          }}
          className="absolute left-72 -translate-x-1/2 bottom-0 z-10"
        >
          <img
            src={profile}
            alt=""
            className="w-[600px]"
          />
        </motion.div>

        {/* Description */}
        <motion.div
          initial={{
            opacity: 0,
            x: 60,
          }}
          animate={{
            opacity: 1,
            x: 0,
          }}
          transition={{
            delay: .5,
          }}
          className="pb-28 ml-auto w-[330px] text-[#d4d4d4] z-20"
        >
          <p className="text-lg leading-8">
            I help founders build thoughtful digital experiences
            that combine beautiful interfaces with strategic UX,
            creating products people genuinely enjoy using.
          </p>
        </motion.div>

      </div>
    </section>
  );
}
